package com.ejemplo.alquileres.controller;

import com.ejemplo.alquileres.model.*;
import com.ejemplo.alquileres.service.*;
import com.ejemplo.alquileres.ui.*;
import java.math.BigDecimal;
import java.time.Clock;
import java.time.LocalDate;
import java.util.List;
import javafx.beans.property.*;
import javafx.collections.*;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import org.springframework.data.domain.Page;
import org.springframework.stereotype.Component;

@Component public class MantenimientoController implements Refrescable {
 private final MantenimientoService service; private final InmuebleService inmuebles; private final ReporteMantenimientoExcelService excel; private final RentabilidadService rentabilidad; private final Clock clock; private final Tareas tareas; private final Notificador aviso; private final Exportador exportador; private final ObservableList<Mantenimiento> datos=FXCollections.observableArrayList(); private List<Mantenimiento> visibles=List.of();
 @FXML private TextField buscar,titulo,costo; @FXML private DatePicker fechaReporte,fechaProgramada; @FXML private ComboBox<EstadoMantenimiento> filtroEstado; @FXML private ComboBox<PrioridadMantenimiento> filtroPrioridad,prioridad; @FXML private ComboBox<CategoriaMantenimiento> filtroCategoria,categoria; @FXML private ComboBox<ResponsablePago> responsable; @FXML private ComboBox<Inmueble> inmueble; @FXML private TextArea descripcion,observaciones; @FXML private VBox drawer; @FXML private TableView<Mantenimiento> tabla; @FXML private TableColumn<Mantenimiento,String> colCodigo,colInmueble,colTitulo,colCategoria,colPrioridad,colEstado,colResponsable,colFecha; @FXML private TableColumn<Mantenimiento,BigDecimal> colCosto; @FXML private Label abiertos,urgentes,enProceso,gastoMes;
 public MantenimientoController(MantenimientoService s,InmuebleService i,ReporteMantenimientoExcelService e,RentabilidadService r,Clock c,Tareas t,Notificador a,Exportador x){service=s;inmuebles=i;excel=e;rentabilidad=r;clock=c;tareas=t;aviso=a;exportador=x;}
 @FXML public void initialize(){filtroEstado.setItems(FXCollections.observableArrayList(EstadoMantenimiento.values()));filtroPrioridad.setItems(FXCollections.observableArrayList(PrioridadMantenimiento.values()));filtroCategoria.setItems(FXCollections.observableArrayList(CategoriaMantenimiento.values()));prioridad.setItems(FXCollections.observableArrayList(PrioridadMantenimiento.values()));categoria.setItems(FXCollections.observableArrayList(CategoriaMantenimiento.values()));responsable.setItems(FXCollections.observableArrayList(ResponsablePago.values()));colCodigo.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getCodigo()));colInmueble.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getInmueble().getNombre()));colTitulo.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getTitulo()));colCategoria.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getCategoria().name()));colPrioridad.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getPrioridad().name()));colEstado.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getEstado().name()));colResponsable.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getResponsablePago().name()));colFecha.setCellValueFactory(c->new SimpleStringProperty(c.getValue().getFechaReporte().toString()));colCosto.setCellValueFactory(c->new SimpleObjectProperty<>(c.getValue().getCostoReal()==null?c.getValue().getCostoEstimado():c.getValue().getCostoReal()));colCosto.setCellFactory(x->moneda());tabla.setItems(datos);buscar.textProperty().addListener((o,a,b)->refrescar());filtroEstado.valueProperty().addListener((o,a,b)->refrescar());filtroPrioridad.valueProperty().addListener((o,a,b)->refrescar());filtroCategoria.valueProperty().addListener((o,a,b)->refrescar());}
 public void refrescar(){tareas.ejecutar(()->new Object[]{service.listar(buscar.getText(),filtroEstado.getValue(),filtroPrioridad.getValue(),null,filtroCategoria.getValue(),0,100),service.resumen()},x->{Page<Mantenimiento> p=(Page<Mantenimiento>)x[0];visibles=p.getContent();datos.setAll(visibles);MantenimientoService.Resumen r=(MantenimientoService.Resumen)x[1];abiertos.setText(String.valueOf(r.abiertos()));urgentes.setText(String.valueOf(r.urgentes()));enProceso.setText(String.valueOf(r.enProceso()));gastoMes.setText(Tablas.moneda(r.gastoMes()));},e->aviso.error(msg(e)));}
 @FXML private void onNuevo(){titulo.clear();descripcion.clear();costo.clear();observaciones.clear();fechaReporte.setValue(LocalDate.now());fechaProgramada.setValue(null);prioridad.setValue(PrioridadMantenimiento.MEDIA);categoria.setValue(CategoriaMantenimiento.OTROS);responsable.setValue(ResponsablePago.PROPIETARIO);tareas.ejecutar(()->inmuebles.listar("",null,null,0,200),p->{inmueble.setItems(FXCollections.observableArrayList(((Page<Inmueble>)p).getContent()));drawer.setVisible(true);drawer.setManaged(true);},e->aviso.error(msg(e)));}
 @FXML private void onGuardar(){try{MantenimientoService.Solicitud s=new MantenimientoService.Solicitud(inmueble.getValue()==null?null:inmueble.getValue().getId(),null,fechaReporte.getValue(),titulo.getText(),descripcion.getText(),categoria.getValue(),prioridad.getValue(),responsable.getValue(),null,null,decimal(costo.getText()),fechaProgramada.getValue(),observaciones.getText());tareas.ejecutar(()->service.registrar(s),x->{cerrar();aviso.info("Mantenimiento registrado.");refrescar();},e->aviso.error(msg(e)));}catch(NumberFormatException e){aviso.error("El costo debe ser un número válido.");}}
 @FXML private void onIniciar(){Mantenimiento m=seleccion();if(m==null)return;CheckBox c=new CheckBox("Poner el inmueble en mantenimiento");new Alert(Alert.AlertType.CONFIRMATION,"¿Iniciar "+m.getCodigo()+"?",ButtonType.OK,ButtonType.CANCEL){ {getDialogPane().setContent(c);} }.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->tareas.ejecutar(()->service.iniciar(m.getId(),c.isSelected()),x->{aviso.info("Mantenimiento iniciado.");refrescar();},e->aviso.error(msg(e))));}
 @FXML private void onResolver(){Mantenimiento m=seleccion();if(m==null)return;DatePicker f=new DatePicker(LocalDate.now());TextField v=new TextField();v.setPromptText("Costo real");VBox box=new VBox(8,new Label("Fecha de resolución"),f,new Label("Costo real (S/)"),v);Alert d=new Alert(Alert.AlertType.CONFIRMATION);d.setHeaderText("Resolver "+m.getCodigo());d.getDialogPane().setContent(box);d.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->{try{tareas.ejecutar(()->service.resolver(m.getId(),f.getValue(),decimal(v.getText())),x->{aviso.info("Mantenimiento resuelto.");refrescar();},e->aviso.error(msg(e)));}catch(NumberFormatException e){aviso.error("El costo debe ser válido.");}});}
 @FXML private void onCancelar(){Mantenimiento m=seleccion();if(m!=null)tareas.ejecutar(()->service.cancelar(m.getId()),x->{aviso.info("Mantenimiento cancelado.");refrescar();},e->aviso.error(msg(e)));}
 @FXML private void onCargo(){Mantenimiento m=seleccion();if(m==null)return;DatePicker f=new DatePicker(LocalDate.now());Alert d=new Alert(Alert.AlertType.CONFIRMATION);d.setHeaderText("Vencimiento del cargo");d.getDialogPane().setContent(f);d.showAndWait().filter(b->b==ButtonType.OK).ifPresent(b->tareas.ejecutar(()->service.generarCargo(m.getId(),f.getValue()),x->{aviso.info("Cargo generado en Cuentas por cobrar.");refrescar();},e->aviso.error(msg(e))));}
 @FXML private void onExportar(){java.io.File destino=exportador.elegirDestino(tabla.getScene()==null?null:tabla.getScene().getWindow(),"reporte-mantenimiento-"+java.time.LocalDate.now()+".xlsx","Excel","xlsx");if(destino==null)return;Periodo.Rango r=Periodo.ESTE_ANIO.resolver(clock,null,null);tareas.ejecutar(()->excel.generar(visibles,rentabilidad.porInmueble(r.desde(),r.hasta()),r.desde(),r.hasta()),bytes->{exportador.escribir(destino,bytes);aviso.info("Excel generado.");},e->aviso.error(msg(e)));} @FXML private void onCerrar(){cerrar();}private void cerrar(){drawer.setVisible(false);drawer.setManaged(false);}private Mantenimiento seleccion(){Mantenimiento m=tabla.getSelectionModel().getSelectedItem();if(m==null)aviso.error("Selecciona un mantenimiento.");return m;}private TableCell<Mantenimiento,BigDecimal> moneda(){return new TableCell<>(){protected void updateItem(BigDecimal v,boolean e){super.updateItem(v,e);setText(e||v==null?"":Tablas.moneda(v));}};}private BigDecimal decimal(String v){return v==null||v.isBlank()?null:new BigDecimal(v.trim().replace(',','.'));}private String msg(Throwable e){return e.getCause()!=null&&e.getCause().getMessage()!=null?e.getCause().getMessage():e.getMessage();}
}
